(function () {
  "use strict";

  const SOURCES = {
    dawid1984: {kind:"Primary paper", label:"Dawid (1984), The Prequential Approach", href:"https://doi.org/10.2307/2981683"},
    cifar: {kind:"Official dataset", label:"Krizhevsky, Nair & Hinton, CIFAR-10 and CIFAR-100 datasets", href:"https://www.cs.toronto.edu/~kriz/cifar.html"},
    mnist: {kind:"Official dataset", label:"LeCun, Cortes & Burges, The MNIST Database", href:"https://yann.lecun.org/exdb/mnist/index.html"},
    scenarios: {kind:"Primary paper", label:"van de Ven & Tolias (2019), Three scenarios for continual learning", href:"https://arxiv.org/abs/1904.07734"},
    gem: {kind:"Primary paper", label:"Lopez-Paz & Ranzato (2017), Gradient Episodic Memory", href:"https://papers.nips.cc/paper/7225-gradient-episodic-memory-for-continual-learning"},
    catastrophic: {kind:"Foundational paper", label:"McCloskey & Cohen (1989), Catastrophic Interference in Connectionist Networks", href:"https://doi.org/10.1016/S0079-7421(08)60536-8"},
    permuted: {kind:"Primary study", label:"Goodfellow et al. (2013), An Empirical Investigation of Catastrophic Forgetting", href:"https://arxiv.org/abs/1312.6211"},
    backprop: {kind:"Foundational paper", label:"Rumelhart, Hinton & Williams (1986), Learning representations by back-propagating errors", href:"https://doi.org/10.1038/323533a0"},
    predictiveCoding: {kind:"Primary paper", label:"Whittington & Bogacz (2017), Predictive coding with local Hebbian plasticity", href:"https://doi.org/10.1162/NECO_a_00949"},
    rsa: {kind:"Primary paper", label:"Kriegeskorte, Mur & Bandettini (2008), Representational Similarity Analysis", href:"https://doi.org/10.3389/neuro.06.004.2008"},
    adam: {kind:"Primary paper", label:"Kingma & Ba (2014), Adam: A Method for Stochastic Optimization", href:"https://arxiv.org/abs/1412.6980"},
    sgd: {kind:"Foundational paper", label:"Robbins & Monro (1951), A Stochastic Approximation Method", href:"https://doi.org/10.1214/aoms/1177729586"},
    weightDecay: {kind:"Primary paper", label:"Loshchilov & Hutter (2017), Decoupled Weight Decay Regularization", href:"https://arxiv.org/abs/1711.05101"},
    deepLearningBook: {kind:"Reference book", label:"Goodfellow, Bengio & Courville (2016), Deep Learning", href:"https://www.deeplearningbook.org/"},
    causalBook: {kind:"Reference text", label:"Hernán & Robins, Causal Inference: What If", href:"https://www.hsph.harvard.edu/miguel-hernan/causal-inference-book/"},
    projectMetrics: {kind:"Project operational source", label:"Continual evaluator implementation", href:"../../playground/step1-static-mnist/continual_experiment.py"},
    projectCifarMetrics: {kind:"Project operational source", label:"SplitCIFAR evaluator implementation", href:"../../playground/step2-cifar10/common.py"},
    projectRepresentations: {kind:"Project operational source", label:"RDM, drift and label-alignment implementation", href:"../../playground/step2-cifar10/representation_viz.py"},
    projectContract: {kind:"Project protocol", label:"Research project contract", href:"../../agents/research-project-contract.md"},
    projectRelaxation: {kind:"Project evaluation", label:"Relaxation and plasticity evaluation", href:"../../agents/research/pc-relaxation-plasticity/04-evaluation.md"},
    projectCifar: {kind:"Project evaluation", label:"Predictive-coding CIFAR evaluation", href:"../../agents/research/predictive-coding-cifar-baseline/04-evaluation.md"}
  };

  const TERMS = [];
  const add = config => TERMS.push(config);

  add({id:"continual-learning",name:"Continual learning",aliases:["continual learning","continual-learning"],category:"Continual-learning regimes",summary:"Learning from a non-stationary sequence while retaining and reusing earlier knowledge.",definition:"A learner receives an ordered stream of experiences whose data distribution or prediction problem changes over time. Evaluation must therefore measure both performance on new data and what happens to previously acquired capabilities.",formula:"D₁, D₂, …, D_T with D_t ≠ D_{t+1};  θ_t = A(θ_{t−1}, D_t)",formulaNote:"The update algorithm A sees the stream in order. Continual learning asks how θ_t performs on both current and earlier distributions.",project:"This project uses explicit task boundaries for evaluation but no model task ID during prediction. Claims are scenario-specific.",sources:["scenarios","gem","projectContract"],related:["class-incremental-learning","domain-incremental-learning","catastrophic-forgetting"]});
  add({id:"online-learning",name:"Online learning",aliases:["online learning","online-learning"],category:"Continual-learning regimes",summary:"Updating a predictor as observations arrive, usually before future observations are known.",definition:"At step t the learner predicts from x_t using parameters θ_t, observes y_t, incurs loss ℓ_t, and updates to θ_{t+1}. Online describes the temporal access pattern; it does not by itself guarantee continual retention.",formula:"ŷ_t = f_{θ_t}(x_t);  ℓ_t = ℓ(ŷ_t,y_t);  θ_{t+1} = U(θ_t, x_t, y_t)",formulaNote:"The prediction precedes the update. Cumulative online loss is Σ_t ℓ_t.",project:"The continual experiments use predict-before-update measurements and one pass through each task stream.",sources:["dawid1984","gem","projectContract"],related:["prequential-evaluation","single-pass","continual-learning"]});
  add({id:"static-training",name:"Static training",aliases:["static training","static learning","stationary","static"],category:"Continual-learning regimes",summary:"Training and evaluating under one fixed task distribution rather than an ordered task stream.",definition:"A single data-generating distribution D defines the training objective. Samples may be revisited for many epochs, so static performance cannot by itself establish continual-learning ability.",formula:"R(θ) = E_{(x,y)∼D}[ℓ(f_θ(x),y)]",formulaNote:"The target distribution D is treated as fixed during optimization.",project:"Static MNIST and CIFAR-10 are implementation and protocol checks; they are not promoted to continual-learning evidence.",sources:["deepLearningBook","projectContract"],related:["continual-learning","epoch","test-set"]});
  add({id:"class-incremental-learning",name:"Class-incremental learning",aliases:["class incremental","class-incremental","class incremental learning","class-incremental learning"],category:"Continual-learning regimes",summary:"New classes arrive over time and the model must classify among all classes seen so far without being told the task.",definition:"Task t introduces a class subset C_t. At evaluation after task t, the prediction space is the union of all observed classes, and no task identifier selects a task-specific output head.",formula:"C_{≤t}=⋃_{k=1}^{t} C_k;  ŷ = argmax_{c∈C_{≤t}} f_θ(x)_c",formulaNote:"Difficulty grows because old and new classes compete in the same output space.",project:"SplitMNIST and SplitCIFAR-10 use one shared ten-way head, five class pairs, and no model task ID.",sources:["scenarios","projectMetrics","projectCifarMetrics"],related:["shared-head","task-id","split-mnist","split-cifar-10"]});
  add({id:"domain-incremental-learning",name:"Domain-incremental learning",aliases:["domain incremental","domain-incremental","domain incremental learning","domain-incremental learning","domain shift"],category:"Continual-learning regimes",summary:"The input distribution changes across experiences while the label space and prediction problem remain shared.",definition:"All tasks use the same classes and output semantics, but each task changes p_t(x|y) or another domain property. The learner is not given a task identifier at test time.",formula:"Y_t = Y for all t, but p_t(x|y) ≠ p_{t+1}(x|y)",formulaNote:"The label set stays fixed; the domain generating the inputs changes.",project:"Permuted MNIST creates domains with fixed pixel permutations while preserving digit labels.",sources:["scenarios","permuted","projectRelaxation"],related:["permuted-mnist","class-incremental-learning","task-id"]});
  add({id:"task-id",name:"Task identity",aliases:["task ID","task identity","model task ID","task-id"],category:"Continual-learning regimes",summary:"Side information telling the model which task or context generated an example.",definition:"A task-aware predictor receives both x and an identifier t. Without task identity, the predictor must use a shared decision rule or infer context from x.",formula:"Task-aware: ŷ=f_θ(x,t);  task-agnostic: ŷ=f_θ(x)",formulaNote:"Providing t can turn one difficult shared classification problem into several easier conditional problems.",project:"The model receives no task ID in SplitMNIST, Permuted MNIST, or SplitCIFAR-10.",sources:["scenarios","projectContract"],related:["shared-head","class-incremental-learning","domain-incremental-learning"]});
  add({id:"shared-head",name:"Shared output head",aliases:["shared head","single output head","shared output head","ten-way head","10 logits"],category:"Continual-learning regimes",summary:"One output layer is used for all tasks instead of selecting a task-specific classifier.",definition:"Every input is scored by the same vector of class logits. All seen classes therefore compete during prediction, which is central to class-incremental evaluation.",formula:"z=f_θ(x)∈R^{|C|};  ŷ=argmax_c z_c",formulaNote:"There is one fixed logit vector z, not a separate z^(t) selected by task identity.",project:"The class-incremental streams use one ten-class output head for all five class-pair tasks.",sources:["scenarios","projectMetrics"],related:["logits","class-incremental-learning","task-id"]});
  add({id:"replay",name:"Replay",aliases:["replay","replay buffer","experience replay","rehearsal"],category:"Continual-learning regimes",summary:"Reintroducing stored or generated past examples while learning new stream data.",definition:"A replay learner updates on a mixture of current observations and samples representing earlier experiences. Replay-free protocols exclude that additional past-data channel.",formula:"B_t = B_t^current ∪ B_t^replay;  B_t^replay ⊂ ⋃_{k<t} D_k",formulaNote:"Replay may store raw examples, features, logits, or generated pseudo-examples.",project:"All continual experiments reported in this frontend are replay-free.",sources:["gem","scenarios","projectContract"],related:["single-pass","continual-learning","catastrophic-forgetting"]});
  add({id:"single-pass",name:"Single-pass stream",aliases:["single pass","single-pass","one pass","one-pass","one pass per task"],category:"Continual-learning regimes",summary:"Each stream example is used for training once rather than revisited over multiple epochs.",definition:"For a stream S=(e₁,…,e_n), the update schedule consumes each e_i once in order. This is an access constraint, not a statement that an algorithm performs only one internal update per batch.",formula:"count_train(e_i)=1 for every stream example e_i",formulaNote:"RBP and PC may perform repeated internal updates while still seeing each external example once.",project:"SplitMNIST, Permuted MNIST and SplitCIFAR-10 are one-pass per task with no replay.",sources:["gem","projectContract"],related:["online-learning","replay","repeated-update-backpropagation"]});

  add({id:"cifar-10",name:"CIFAR-10",aliases:["CIFAR-10","CIFAR 10"],category:"Datasets and benchmarks",summary:"A ten-class benchmark of 60,000 small color images.",definition:"CIFAR-10 contains 60,000 RGB images of size 32×32 in ten object classes: 50,000 training images and 10,000 test images, with 6,000 images per class.",formula:"D_CIFAR10 ⊂ R^{32×32×3}×{1,…,10};  |D|=60,000",formulaNote:"The official split is 50,000 training and 10,000 test images.",project:"The frontend separates a static Figure 4i reproduction from the project-created SplitCIFAR-10 stream.",sources:["cifar","projectCifar"],related:["split-cifar-10","static-training","class-incremental-learning"]});
  add({id:"mnist",name:"MNIST",aliases:["MNIST"],category:"Datasets and benchmarks",summary:"A ten-class benchmark of centered 28×28 grayscale handwritten digits.",definition:"MNIST contains 60,000 training and 10,000 test images. Each image is a 28×28 grayscale array representing one digit from 0 through 9.",formula:"D_MNIST ⊂ [0,255]^{28×28}×{0,…,9};  |D_train|=60,000",formulaNote:"The official test set contains 10,000 examples.",project:"MNIST supplies the static, SplitMNIST and Permuted MNIST protocols.",sources:["mnist","projectRelaxation"],related:["split-mnist","permuted-mnist","cifar-10"]});
  add({id:"split-mnist",name:"SplitMNIST",aliases:["SplitMNIST","Split MNIST","Split-MNIST"],category:"Datasets and benchmarks",summary:"A continual benchmark that partitions MNIST classes into sequential tasks.",definition:"This project partitions digits into five disjoint class pairs and presents the pairs sequentially. A shared ten-way head makes the protocol class-incremental.",formula:"C₁={0,1}, C₂={2,3}, C₃={4,5}, C₄={6,7}, C₅={8,9}",formulaNote:"After task t, evaluation covers all relevant task test sets through one shared output head.",project:"The stream is one-pass, replay-free, uses no model task ID, and reports prequential, adaptation, final, forgetting and BWT jointly.",sources:["scenarios","projectMetrics","projectRelaxation"],related:["mnist","class-incremental-learning","prequential-evaluation"]});
  add({id:"permuted-mnist",name:"Permuted MNIST",aliases:["Permuted MNIST","Permuted-MNIST","permuted mnist"],category:"Datasets and benchmarks",summary:"A domain-incremental benchmark where each task applies a fixed pixel permutation to MNIST images.",definition:"For task t, one bijection π_t permutes the 784 pixel positions for every example in that task. Labels stay unchanged, so tasks share the same ten-class prediction problem but differ in input domain.",formula:"x^(t)_j = x_{π_t(j)},  π_t:{1,…,784}→{1,…,784}",formulaNote:"Each π_t is fixed within a task and differs across tasks.",project:"The project uses identity plus four fixed permutations, one shared head, and no task ID.",sources:["permuted","scenarios","projectRelaxation"],related:["mnist","domain-incremental-learning","random-seed"]});
  add({id:"split-cifar-10",name:"SplitCIFAR-10",aliases:["SplitCIFAR-10","Split CIFAR-10","SplitCIFAR","split-cifar"],category:"Datasets and benchmarks",summary:"A project-defined class-incremental stream formed from five CIFAR-10 class pairs.",definition:"The ten CIFAR-10 classes are divided into five sequential two-class experiences. The model predicts through one ten-way head and is evaluated after every task boundary.",formula:"{1,…,10}=C₁ ⊔ C₂ ⊔ C₃ ⊔ C₄ ⊔ C₅,  |C_t|=2",formulaNote:"The symbol ⊔ denotes disjoint union.",project:"This is a replay-free project extension, not part of the static source-paper Figure 4i claim.",sources:["cifar","projectCifarMetrics","projectCifar"],related:["cifar-10","class-incremental-learning","shared-head"]});

  add({id:"prequential-evaluation",name:"Prequential evaluation",aliases:["prequential","prequential accuracy","predict-before-update","pre-update prequential accuracy"],category:"Metrics and evaluation",summary:"Evaluating each arriving example before using it to update the model.",definition:"Prequential, or predictive-sequential, evaluation scores the learner on the stream in temporal order. For classification, the project records whether the current model predicts each incoming labeled example correctly before training on it.",formula:"Acc_pre = (1/N) Σ_{t=1}^{N} 𝟙[argmax_c f_{θ_t}(x_t)_c = y_t]",formulaNote:"θ_t is the parameter state before the update using (x_t,y_t). The metric therefore measures online acquisition without train-on-test leakage at that step.",project:"The implementation aggregates predict-before-update correctness across the stream and also reports it by incoming task.",sources:["dawid1984","projectMetrics","projectCifarMetrics"],related:["online-learning","adaptation-gain","accuracy"]});
  add({id:"accuracy",name:"Classification accuracy",aliases:["accuracy","test accuracy","validation accuracy","final accuracy"],category:"Metrics and evaluation",summary:"The fraction of evaluated examples assigned the correct class.",definition:"For a labeled evaluation set, accuracy is the empirical mean of the zero-one correctness indicator. It depends on the exact evaluation set and parameter checkpoint.",formula:"Acc(θ;D) = (1/|D|) Σ_{(x,y)∈D} 𝟙[argmax_c f_θ(x)_c = y]",formulaNote:"Multiplying by 100 expresses the value as a percentage.",project:"The frontend labels validation, test, prequential and final-average accuracy separately to prevent metric substitution.",sources:["deepLearningBook","projectMetrics"],related:["final-average-accuracy","test-set","validation-set"]});
  add({id:"final-average-accuracy",name:"Final average accuracy",aliases:["final average","final average accuracy","final performance"],category:"Metrics and evaluation",summary:"Mean task accuracy after the final task has been learned.",definition:"Let R_{t,i} denote accuracy on task i after training through task t. With T tasks, final average accuracy averages the final row of the accuracy matrix.",formula:"ACC_final = (1/T) Σ_{i=1}^{T} R_{T,i}",formulaNote:"This compresses old- and new-task performance into one number, so the full matrix and acquisition metrics remain important.",project:"The project computes this directly from the last evaluation row.",sources:["gem","projectMetrics"],related:["accuracy","average-forgetting","adaptation-gain"]});
  add({id:"adaptation-gain",name:"Adaptation gain",aliases:["adaptation","adaptation gain","mean adaptation gain","acquisition"],category:"Metrics and evaluation",summary:"How much performance on a task improves while that task is being learned.",definition:"For task i, subtract accuracy immediately before its training from accuracy immediately after its training. The project reports the mean across tasks.",formula:"A_i = R_{i+1,i} − R_{i,i};  A_mean=(1/T)Σ_i A_i",formulaNote:"The matrix includes a pre-training row, hence the i+1 indexing in the project evaluator.",project:"Adaptation is a plasticity measure and must accompany forgetting: a model cannot preserve knowledge it never acquired.",sources:["projectMetrics","projectRelaxation"],related:["prequential-evaluation","average-forgetting","stability-plasticity-trade-off"]});
  add({id:"average-forgetting",name:"Average forgetting",aliases:["forgetting","average forgetting","measured forgetting"],category:"Metrics and evaluation",summary:"Average loss from each old task's best post-learning accuracy to its final accuracy.",definition:"For every task except the last, find its highest recorded accuracy after that task was introduced and subtract its accuracy after the final task. Average these losses.",formula:"F = (1/(T−1)) Σ_{i=1}^{T−1} [max_{t≥i+1} R_{t,i} − R_{T,i}]",formulaNote:"Lower F is better only when acquisition is comparable; weakly learned tasks can have little left to forget.",project:"This exact maximum-to-final formula is implemented in both continual evaluators.",sources:["gem","projectMetrics","projectCifarMetrics"],related:["backward-transfer","adaptation-gain","catastrophic-forgetting"]});
  add({id:"backward-transfer",name:"Backward transfer (BWT)",aliases:["backward transfer","BWT"],category:"Metrics and evaluation",summary:"Change in old-task performance between post-task learning and the end of the stream.",definition:"The project compares final accuracy on each old task with accuracy immediately after that task was trained. Positive values mean later learning improved old tasks; negative values indicate interference.",formula:"BWT = (1/(T−1)) Σ_{i=1}^{T−1} [R_{T,i} − R_{i+1,i}]",formulaNote:"Under the present evaluation grids BWT is closely related to, and often exactly the negative of, forgetting, but the definitions are not universally identical.",project:"The frontend reports BWT beside average forgetting rather than treating it as independent evidence when they are algebraically redundant.",sources:["gem","projectMetrics","projectRelaxation"],related:["average-forgetting","final-average-accuracy","catastrophic-forgetting"]});
  add({id:"catastrophic-forgetting",name:"Catastrophic forgetting",aliases:["catastrophic forgetting","catastrophically forget","catastrophic-forgetting"],category:"Metrics and evaluation",summary:"A severe loss of previously learned performance caused by subsequent learning.",definition:"Catastrophic forgetting is not ordinary statistical fluctuation: performance on earlier tasks collapses after optimizing on later tasks because shared parameters or representations interfere.",formula:"R_{i+1,i} high, but R_{T,i} ≪ R_{i+1,i}",formulaNote:"The magnitude can be summarized by forgetting or negative BWT, but the adjective catastrophic is a substantive description of a large collapse.",project:"SplitMNIST and SplitCIFAR-10 end near severe forgetting levels for both compared methods.",sources:["catastrophic","permuted","projectContract"],related:["average-forgetting","continual-learning","stability-plasticity-trade-off"]});
  add({id:"stability-plasticity-trade-off",name:"Stability–plasticity trade-off",aliases:["stability–plasticity","stability-plasticity","stability plasticity","stability–plasticity trade-off","acquisition–retention trade-off","acquisition-retention trade-off"],category:"Metrics and evaluation",summary:"The tension between preserving old behavior and changing enough to learn new behavior.",definition:"Stability describes resistance to harmful change; plasticity describes capacity for useful adaptation. A method is not a continual-learning success if apparent stability is obtained mainly by failing to acquire the new task.",formula:"Seek: minimize F(θ) subject to A(θ) ≥ A_min and P(θ) ≥ P_min",formulaNote:"F is forgetting, A adaptation, and P prequential performance. The constraint form makes the joint requirement explicit.",project:"The project reads forgetting jointly with adaptation, prequential and final accuracy.",sources:["catastrophic","projectContract","projectRelaxation"],related:["adaptation-gain","average-forgetting","representation-drift"]});
  add({id:"percentage-point",name:"Percentage point (pp)",aliases:["percentage point","percentage points","pp"],category:"Metrics and evaluation",summary:"An absolute difference between two percentages.",definition:"A percentage-point difference subtracts percentage values directly. It is not the same as a relative percentage change.",formula:"Δ_pp = 100(a−b);  relative change = (a−b)/b",formulaNote:"For a=0.72 and b=0.70, the difference is 2 pp but the relative increase is about 2.86%.",project:"Result cards use pp for method differences and registered tolerances.",sources:["projectContract"],related:["accuracy","paired-design"]});

  add({id:"backpropagation",name:"Backpropagation (BP)",aliases:["backpropagation","backprop","BP"],category:"Learning methods",summary:"Computing parameter gradients by applying the chain rule backward through a differentiable computation graph.",definition:"For a composed network and scalar loss, backpropagation efficiently reuses intermediate derivatives to compute the gradient with respect to every parameter.",formula:"δ^L=∂ℓ/∂z^L;  δ^l=(W^{l+1})ᵀδ^{l+1}⊙φ'(z^l);  ∂ℓ/∂W^l=δ^l(a^{l−1})ᵀ",formulaNote:"The backward recursion is an application of the multivariate chain rule.",project:"MNIST uses a fresh BP control. The archived CIFAR comparator called BP is specifically repeated-update RBP and is labeled separately.",sources:["backprop","deepLearningBook","projectContract"],related:["repeated-update-backpropagation","predictive-coding","stochastic-gradient-descent"]});
  add({id:"repeated-update-backpropagation",name:"Repeated-update backpropagation (RBP)",aliases:["RBP","repeated-update BP","repeated update BP","repeated-update backpropagation","archived RBP"],category:"Learning methods",summary:"This project's name for the archived CIFAR control that performs multiple BP/Adam parameter updates on each external batch.",definition:"RBP is not a universal standard acronym here. It distinguishes the source-paper comparator from conventional one-update-per-batch BP and prevents an unfair semantic collapse between different update budgets.",formula:"θ_{k+1}=Adam(θ_k,∇_θℓ(B;θ_k)),  k=0,…,K−1 with K=16",formulaNote:"The same external batch B is reused for K internal parameter updates in the archived protocol.",project:"CIFAR experiments use 16 Adam updates per batch. A conventional one-update BP comparator remains a proposed follow-up.",sources:["projectCifar","backprop","adam"],related:["backpropagation","single-pass","adam"]});
  add({id:"predictive-coding",name:"Predictive coding (PC)",aliases:["predictive coding","Predictive Coding","PC"],category:"Learning methods",summary:"An iterative energy-based learning scheme using local prediction errors and latent-state relaxation.",definition:"A hierarchical predictive-coding network defines layerwise predictions and errors. Inference updates latent activities to reduce an energy; parameter updates then use local activity–error products. Exact variants and update schedules matter.",formula:"E(v,θ)=Σ_l ½‖v_l−f_l(v_{l−1};θ_l)‖²;  v←v−η_v∇_vE;  θ←θ−η_θ∇_θE",formulaNote:"The latent-state update is relaxation. Under specific assumptions, PC weight updates can approximate BP; this is not automatic for every implementation.",project:"The experiments vary relaxation depth T and distinguish updating parameters at the last inference step versus all steps.",sources:["predictiveCoding","projectContract","projectRelaxation"],related:["relaxation","backpropagation","half-squared-error"]});
  add({id:"relaxation",name:"Relaxation / inference steps",aliases:["relaxation","relaxation depth","inference steps","inference iteration","inference iterations","inference budget"],category:"Learning methods",summary:"Iterative latent-state optimization performed before or during a predictive-coding parameter update.",definition:"Starting from initialized latent activities, predictive coding applies T state-update steps intended to reduce its inference energy. Too few steps can leave upstream error information poorly propagated; more steps increase compute and need not improve the final task metric.",formula:"v^{(τ+1)}=v^{(τ)}−η_v∇_vE(v^{(τ)},θ),  τ=0,…,T−1",formulaNote:"T is the relaxation depth; convergence should be diagnosed from the objective or updates, not assumed from T alone.",project:"The MNIST sweep evaluates T∈{1,5,10,20}; T=1 is a propagation-deficient boundary in the tested architecture.",sources:["predictiveCoding","projectRelaxation"],related:["predictive-coding","wall-clock-time","update-alignment"]});
  add({id:"stochastic-gradient-descent",name:"Stochastic gradient descent (SGD)",aliases:["SGD","stochastic gradient descent","gradient descent"],category:"Learning methods",summary:"Updating parameters using a gradient estimated from a sample or mini-batch.",definition:"Instead of differentiating the full-data objective at every step, SGD uses an unbiased or approximate mini-batch gradient. The learning rate scales the update.",formula:"g_t=(1/|B_t|)Σ_{i∈B_t}∇_θℓ_i(θ_t);  θ_{t+1}=θ_t−η_t g_t",formulaNote:"Full-batch gradient descent is the special case B_t equal to the full training set.",project:"SGD appears in latent-state updates and as the conventional optimizer concept contrasted with Adam-based archived controls.",sources:["sgd","deepLearningBook"],related:["adam","learning-rate","batch-size"]});
  add({id:"adam",name:"Adam",aliases:["Adam"],category:"Learning methods",summary:"An adaptive first-order optimizer using exponential moving averages of gradients and squared gradients.",definition:"Adam maintains biased first- and second-moment estimates, corrects their initialization bias, and scales each coordinate of the parameter update by its estimated root second moment.",formula:"m_t=β₁m_{t−1}+(1−β₁)g_t;  v_t=β₂v_{t−1}+(1−β₂)g_t²;  θ_t=θ_{t−1}−η m̂_t/(√v̂_t+ε)",formulaNote:"Hats denote bias-corrected moment estimates.",project:"The archived CIFAR RBP control performs 16 Adam parameter updates per external batch.",sources:["adam","projectCifar"],related:["stochastic-gradient-descent","learning-rate","weight-decay"]});
  add({id:"learning-rate",name:"Learning rate",aliases:["learning rate","LR","step size"],category:"Learning methods",summary:"The scalar controlling the magnitude of an optimization update.",definition:"A learning rate multiplies an update direction. Different parameter groups or latent variables may use different rates, and changing it can alter both convergence and continual plasticity.",formula:"θ_{t+1}=θ_t−η_t d_t",formulaNote:"η_t is the learning rate and d_t is a gradient or optimizer-transformed direction.",project:"The CIFAR reproduction uses source-winning per-method/per-seed rates; proposed causal work varies early-layer plasticity through learning rate.",sources:["deepLearningBook","projectCifar"],related:["stochastic-gradient-descent","adam","random-seed"]});
  add({id:"weight-decay",name:"Weight decay",aliases:["weight decay","L2 regularization","L2 penalty"],category:"Learning methods",summary:"Shrinking parameter magnitudes during optimization, often through an L2 penalty or a decoupled decay step.",definition:"Classical L2 regularization adds a squared-norm penalty to the objective. Decoupled weight decay directly scales parameters; the two operations are not identical for every adaptive optimizer.",formula:"L_reg(θ)=L(θ)+(λ/2)‖θ‖²;  SGD: θ←(1−ηλ)θ−η∇L",formulaNote:"λ controls regularization strength. With Adam, implementation semantics should be stated explicitly.",project:"The archived CIFAR RBP setting reports weight decay 0.01.",sources:["weightDecay","deepLearningBook","projectCifar"],related:["adam","stochastic-gradient-descent","parameter-count"]});
  add({id:"half-squared-error",name:"Half squared error",aliases:["half squared error","half-squared error","squared error","one-hot half squared error"],category:"Learning methods",summary:"A quadratic objective scaled by one half so its derivative has no factor of two.",definition:"For model output z and target vector y, the objective penalizes Euclidean distance. In this project y is a one-hot class vector.",formula:"ℓ(z,y)=½‖z−y‖²₂;  ∂ℓ/∂z=z−y",formulaNote:"The factor ½ is algebraic convenience; it does not change the minimizer.",project:"Both MNIST and source-derived CIFAR models use one-hot half squared error rather than cross-entropy.",sources:["deepLearningBook","projectContract"],related:["logits","predictive-coding","backpropagation"]});
  add({id:"logits",name:"Logits",aliases:["logits","logit"],category:"Learning methods",summary:"Unnormalized real-valued class scores produced before a decision or probability normalization.",definition:"A K-class classifier returns z∈R^K. The predicted class is usually the largest logit; softmax converts logits into normalized positive probabilities.",formula:"ŷ=argmax_k z_k;  softmax(z)_k=e^{z_k}/Σ_j e^{z_j}",formulaNote:"Adding the same constant to every logit leaves softmax probabilities unchanged.",project:"The shared ten-way head produces ten logits; representation diagnostics also measure the logits layer.",sources:["deepLearningBook","projectRepresentations"],related:["shared-head","accuracy","representation"]});
  add({id:"update-alignment",name:"Update alignment",aliases:["update alignment","gradient alignment","PC–BP update cosine","update cosine"],category:"Learning methods",summary:"Directional similarity between two parameter-update vectors.",definition:"Flatten corresponding updates from two learning rules and compute cosine similarity. Alignment near 1 means similar directions, 0 means orthogonal directions, and −1 means opposing directions; norms must be reported separately.",formula:"align(Δθ^a,Δθ^b)=(Δθ^a·Δθ^b)/(‖Δθ^a‖₂‖Δθ^b‖₂)",formulaNote:"Cosine is undefined for a zero vector, so implementations need an explicit convention or exclusion rule.",project:"Layerwise PC–BP update alignment is proposed to test whether deep or low-relaxation PC produces poor credit signals.",sources:["predictiveCoding","projectContract"],related:["cosine-similarity","signal-to-noise-ratio","relaxation"]});
  add({id:"cosine-similarity",name:"Cosine similarity",aliases:["cosine similarity","cosine"],category:"Learning methods",summary:"The normalized dot product measuring the angle between two nonzero vectors.",definition:"Cosine similarity removes vector magnitude and compares direction. It is therefore useful for update alignment but cannot show whether an update is too small or too large.",formula:"cos(a,b)=aᵀb/(‖a‖₂‖b‖₂) ∈ [−1,1]",formulaNote:"The measure is invariant to positive rescaling of either vector.",project:"It is planned as one component of the update-fidelity diagnostic, alongside update norms and SNR.",sources:["deepLearningBook","projectContract"],related:["update-alignment","signal-to-noise-ratio","rdm"]});
  add({id:"signal-to-noise-ratio",name:"Signal-to-noise ratio (SNR)",aliases:["signal-to-noise","signal to noise","signal-to-noise ratio","SNR"],category:"Learning methods",summary:"A ratio comparing the magnitude of a reproducible signal with variability treated as noise.",definition:"SNR has no single universal estimator. A study must define the sampling unit, signal statistic, noise statistic, aggregation level and scale behavior before interpreting it.",formula:"SNR = ‖E[g]‖₂ / √(E[‖g−E[g]‖²₂])",formulaNote:"This is one vector-update definition; the planned project diagnostic remains unverified until its estimator is preregistered.",project:"The frontend labels SNR as a proposed diagnostic, not an observed result.",sources:["projectContract"],related:["update-alignment","random-seed","observational-result"]});

  add({id:"representation",name:"Representation",aliases:["representation","representations","internal representation","feature representation"],category:"Representations",summary:"The activation pattern a model assigns to an input at a chosen layer.",definition:"For a layer l, a representation function maps an input to a vector or tensor h_l(x). Analyses must name the layer, checkpoint, input anchors and any flattening or normalization.",formula:"h_l : X → R^{d_l};  H_l=[h_l(x₁)ᵀ;…;h_l(x_n)ᵀ]",formulaNote:"H_l is the n×d_l matrix of representations for n anchor inputs.",project:"The CIFAR diagnostic records conv1, conv2, fc1 and logits on fixed anchors at task boundaries.",sources:["rsa","projectRepresentations"],related:["rdm","representation-drift","fixed-anchor"]});
  add({id:"convolutional-layer",name:"Convolutional layer",aliases:["convolutional layer","ConvNet","conv1","conv2","Conv"],category:"Representations",summary:"A layer applying shared local filters across spatial positions.",definition:"A convolutional layer produces feature maps by applying kernels to local input neighborhoods. Weight sharing makes the same kernel detect a feature at different positions.",formula:"h_{k,i,j}=φ(b_k+Σ_cΣ_{u,v} W_{k,c,u,v}x_{c,i+u,j+v})",formulaNote:"k indexes output channels; c input channels; (u,v) kernel offsets.",project:"The CIFAR model uses two convolutional layers with 64 and 128 output channels.",sources:["deepLearningBook","projectCifar"],related:["fully-connected-layer","representation","parameter-count"]});
  add({id:"fully-connected-layer",name:"Fully connected layer",aliases:["fully connected layer","dense layer","FC","fc1"],category:"Representations",summary:"A layer in which every output unit receives a weighted contribution from every input feature.",definition:"A fully connected or dense layer applies an affine map followed optionally by a nonlinearity.",formula:"h=φ(Wx+b)",formulaNote:"W has one learned weight for each input–output pair.",project:"The MNIST MLPs are fully connected; the CIFAR model includes a 512-unit fc1 layer before ten logits.",sources:["deepLearningBook","projectContract"],related:["convolutional-layer","logits","model-depth"]});
  add({id:"rdm",name:"Representational dissimilarity matrix (RDM)",aliases:["RDM","representational dissimilarity matrix","dissimilarity matrix"],category:"Representations",summary:"A matrix describing pairwise dissimilarities among stimulus representations.",definition:"For n anchor inputs, an RDM is an n×n symmetric matrix. This project centers each representation vector and uses correlation distance, one minus the Pearson/cosine correlation between centered vectors.",formula:"RDM_{ij}=1−corr(h(x_i),h(x_j));  RDM_{ii}=0",formulaNote:"The upper triangle contains the unique pairwise geometry used by the drift statistic.",project:"Aggregate inference remains in original RDM space; low-dimensional MDS plots are descriptive views only.",sources:["rsa","projectRepresentations","projectCifar"],related:["representation","representation-drift","label-alignment"]});
  add({id:"representation-drift",name:"Representation drift",aliases:["representation drift","representational drift","RDM drift","old-task drift","drift"],category:"Representations",summary:"Change in a model's representation geometry between two checkpoints.",definition:"The project compares two RDMs for the same old-task anchors. Drift is one minus the correlation between their upper triangles, so identical geometry gives zero and larger values mean less similar geometry.",formula:"drift(R⁰,Rᵗ)=1−corr(vec△(R⁰), vec△(Rᵗ))",formulaNote:"vec△ extracts the strict upper triangle. Drift is geometric change, not automatically harmful forgetting or beneficial plasticity.",project:"PC shows lower drift at every measured layer, but also weaker label-aligned acquisition; causality is not established.",sources:["rsa","projectRepresentations","projectCifar"],related:["rdm","label-alignment","stability-plasticity-trade-off"]});
  add({id:"label-alignment",name:"Label alignment",aliases:["label alignment","label-alignment","label-aligned","label structure"],category:"Representations",summary:"Correlation between pairwise representation distance and whether two anchors have different labels.",definition:"For every anchor pair, the project correlates RDM distance with a binary different-class indicator. Positive values mean different-label pairs tend to be farther apart than same-label pairs.",formula:"LA = corr({RDM_{ij}}_{i<j}, {𝟙[y_i≠y_j]}_{i<j})",formulaNote:"This is a project operational diagnostic, not a universal definition of label alignment. It is descriptive and pairwise observations are not independent experimental units.",project:"Initial-to-final gain in LA measures development of label-aligned geometry at conv1, conv2, fc1 and logits.",sources:["projectRepresentations","rsa","projectCifar"],related:["rdm","representation-drift","confounding"]});
  add({id:"fixed-anchor",name:"Fixed anchor set",aliases:["fixed anchors","fixed anchor","anchor set","anchors","anchor"],category:"Representations",summary:"A frozen set of inputs evaluated repeatedly so representation changes are comparable over time.",definition:"Let A contain the same indexed examples at every checkpoint. Holding A fixed makes a change in H_t(A) attributable to the model state or instrumentation rather than to resampling different inputs.",formula:"A={x₁,…,x_n} fixed;  compare H_{t₁}(A) with H_{t₂}(A)",formulaNote:"Class balance and anchor sampling seeds are part of the diagnostic definition.",project:"The SplitCIFAR diagnostic uses 20 fixed samples per class and an isolated anchor RNG.",sources:["projectRepresentations","projectCifar"],related:["representation","checkpoint","paired-design"]});
  add({id:"checkpoint",name:"Checkpoint",aliases:["checkpoint","checkpoints","task-boundary checkpoint"],category:"Representations",summary:"A recorded model state or evaluation point in training.",definition:"A checkpoint identifies parameters θ_t and often optimizer state at a specific training event. Representation comparisons require the checkpoint semantics to be consistent across methods.",formula:"C_t=(θ_t,s_t);  metric_t=M(C_t,D_eval)",formulaNote:"s_t denotes optional optimizer or scheduler state.",project:"Representation diagnostics record initialization and each of five task-boundary checkpoints.",sources:["deepLearningBook","projectRepresentations"],related:["task-boundary","representation-drift","epoch"]});
  add({id:"task-boundary",name:"Task boundary",aliases:["task boundary","task boundaries","boundary evaluation"],category:"Representations",summary:"The transition point between two defined experiences in a continual stream.",definition:"A boundary after task t is an evaluation event before task t+1 begins. Boundary-aware analysis can measure the full accuracy matrix even when the model itself is not given a task identifier.",formula:"Train(D_t) → Evaluate(D₁,…,D_T) → Train(D_{t+1})",formulaNote:"Evaluator knowledge of boundaries does not imply model access to task identity.",project:"Behavior and representation metrics are recorded at every task boundary.",sources:["projectMetrics","projectContract"],related:["task-id","checkpoint","continual-learning"]});

  add({id:"random-seed",name:"Random seed",aliases:["random seed","seed","seeds","RNG","random-number generator"],category:"Experimental design",summary:"An initialization value used to reproduce a pseudorandom sequence.",definition:"A seed indexes one realized sequence of random choices. Repeating experiments over seeds samples implementation variability, but the independent statistical unit depends on what the seed jointly controls.",formula:"ω_s = PRNG(s);  result_s = F(ω_s, protocol)",formulaNote:"A deterministic seed does not remove randomness as a scientific factor; it makes one realization reproducible.",project:"Most project comparisons pair methods on the same seed, initialization and realized stream.",sources:["projectContract","projectRelaxation"],related:["paired-design","confounding","validation-set"]});
  add({id:"paired-design",name:"Paired experimental design",aliases:["paired design","paired seeds","paired seed","matched initialization","paired initialization"],category:"Experimental design",summary:"Comparing methods on matched stochastic realizations to reduce nuisance variation.",definition:"For each seed or unit s, compute a within-pair difference between methods before aggregating. This preserves the covariance created by shared initialization, data order or stream realization.",formula:"d_s = m_s^A−m_s^B;  d̄=(1/S)Σ_s d_s",formulaNote:"The number of paired seeds S, not nested task rows, is usually the independent replication count.",project:"The frontend distinguishes three paired seeds from task-level descriptive rows.",sources:["projectContract","projectCifar"],related:["random-seed","confounding","percentage-point"]});
  add({id:"validation-set",name:"Validation set",aliases:["validation set","validation","validation-only","validation trajectory"],category:"Experimental design",summary:"Held-out data used for model selection or tuning rather than final reporting.",definition:"A validation set supports choices such as learning rate, early stopping or checkpoint selection. Reusing the test set for selection biases the apparent final performance.",formula:"θ̂=argmin_{θ∈C} L_val(θ);  report L_test(θ̂)",formulaNote:"C is the candidate set. The test set should not influence the selection of θ̂ in a clean evaluation.",project:"Proposed fair-budget comparisons require validation-only selection; the archived Figure 4i test-informed rule is reproduced and explicitly labeled.",sources:["deepLearningBook","projectContract"],related:["test-set","checkpoint","learning-rate"]});
  add({id:"test-set",name:"Test set",aliases:["test set","test data","best test epoch","test-informed"],category:"Experimental design",summary:"Held-out data reserved for estimating generalization after model choices are fixed.",definition:"The test set estimates performance on unseen samples from the target distribution. Selecting hyperparameters or epochs on test performance leaks test information into the model-selection process.",formula:"Generalization estimate = (1/|D_test|)Σ_{(x,y)∈D_test}ℓ(f_{θ̂}(x),y)",formulaNote:"θ̂ should normally be fixed without consulting D_test.",project:"The static CIFAR reproduction intentionally mirrors an archived best-test rule and limits its claim accordingly.",sources:["deepLearningBook","projectCifar"],related:["validation-set","accuracy","static-training"]});
  add({id:"epoch",name:"Epoch / training pass",aliases:["epoch","epochs","training pass","training passes","pass"],category:"Experimental design",summary:"One traversal of a defined training dataset.",definition:"If a dataset contains N examples and mini-batches partition it once, an epoch contains approximately N/B update batches. Epoch semantics differ from a single-pass continual stream when tasks or examples cannot be revisited.",formula:"updates per epoch ≈ ⌈N/B⌉",formulaNote:"Repeated internal updates per batch can make parameter-update count much larger than batch count.",project:"Static experiments use repeated epochs or passes; continual streams use one pass per task.",sources:["deepLearningBook","projectContract"],related:["batch-size","single-pass","repeated-update-backpropagation"]});
  add({id:"batch-size",name:"Batch and batch size",aliases:["batch","batches","batch size","mini-batch","minibatch"],category:"Experimental design",summary:"A group of examples used together to estimate an update.",definition:"A mini-batch B_t contains examples whose losses are aggregated before an optimizer step. Batch size affects gradient variance, compute, memory and the meaning of update-count comparisons.",formula:"L_B(θ)=(1/|B|)Σ_{i∈B}ℓ_i(θ)",formulaNote:"One external batch can still receive multiple internal parameter updates.",project:"The source-derived CIFAR protocol uses batch size 200 and repeated updates in RBP.",sources:["deepLearningBook","projectCifar"],related:["stochastic-gradient-descent","epoch","wall-clock-time"]});
  add({id:"parameter-count",name:"Parameter count",aliases:["parameter count","parameters","learned parameters","params"],category:"Experimental design",summary:"The number of learned scalar values in a model.",definition:"For a dense layer the count includes every matrix weight and bias; for a convolution it includes kernel weights shared across spatial positions plus biases.",formula:"Dense: d_out(d_in+1);  Conv2D: c_out(c_in k_h k_w+1)",formulaNote:"Parameter count measures model storage/capacity, not activation memory or total training compute.",project:"Width and depth interventions report parameter multipliers separately from accuracy and runtime.",sources:["deepLearningBook","projectContract"],related:["convolutional-layer","fully-connected-layer","memory-footprint"]});
  add({id:"wall-clock-time",name:"Wall-clock time",aliases:["wall-clock","wall clock","runtime","synchronized runtime","update time","training-loop time"],category:"Experimental design",summary:"Elapsed real time measured for an operation under a stated hardware and synchronization protocol.",definition:"Wall-clock time includes actual implementation and system effects. Accelerator operations must be synchronized before timing boundaries or asynchronous execution can understate elapsed work.",formula:"t_elapsed = t_stop(sync) − t_start(sync)",formulaNote:"A runtime ratio is meaningful only for matched hardware, workload boundaries and synchronization.",project:"The frontend reports synchronized ratios and avoids presenting them as hardware-independent algorithmic complexity.",sources:["projectContract","projectCifar"],related:["batch-size","parameter-count","relaxation"]});
  add({id:"memory-footprint",name:"Memory footprint",aliases:["memory footprint","peak memory","peak allocated memory","GPU memory","memory"],category:"Experimental design",summary:"The amount of storage occupied by parameters, activations, optimizer state and temporary computation.",definition:"Training memory is broader than parameter storage. Peak allocated accelerator memory depends on the implementation, batch size, saved activations, latent states and allocator semantics.",formula:"M_train ≈ M_params + M_grads + M_optimizer + M_activations + M_temporary",formulaNote:"This decomposition is conceptual; allocator-reported peaks are implementation- and device-specific.",project:"PC relaxation adds temporary latent-state cost; CIFAR result cards report peak allocated memory as a scoped resource observation.",sources:["deepLearningBook","projectCifar"],related:["parameter-count","batch-size","wall-clock-time"]});
  add({id:"confounding",name:"Confounding",aliases:["confounding","confounded","task-confounded"],category:"Experimental design",summary:"A mixing of effects that prevents an observed association from identifying the relationship of interest.",definition:"A variable C confounds an exposure X and outcome Y when it influences or indexes both, so their marginal association combines the target relationship with differences induced by C.",formula:"P(Y|X) ≠ P(Y|do(X)) when common causes C are uncontrolled",formulaNote:"The do-notation distinguishes observation from intervention.",project:"Task rows share seeds and task difficulty; drift–forgetting correlations across those rows are observational and task-confounded.",sources:["causalBook","projectCifar"],related:["causal-claim","mediation","observational-result"]});
  add({id:"mediation",name:"Mediation",aliases:["mediation","mediator","drift-mediated"],category:"Experimental design",summary:"A causal pathway in which an exposure changes an intermediate variable that then changes an outcome.",definition:"Calling representation drift a mediator requires more than correlation: one must identify causal effects along X→M and M→Y under explicit assumptions or interventions.",formula:"Total effect = E[Y|do(X=1)]−E[Y|do(X=0)];  indirect effect concerns paths through M",formulaNote:"Exact natural direct/indirect effects require additional counterfactual definitions and identification assumptions.",project:"Current RDM evidence does not establish that low drift mediates lower forgetting.",sources:["causalBook","projectCifar"],related:["confounding","causal-claim","representation-drift"]});
  add({id:"causal-claim",name:"Causal claim",aliases:["causal claim","causal","causality","causal mechanism","cause"],category:"Experimental design",summary:"A statement about how an outcome would change under an intervention.",definition:"A causal effect compares potential outcomes or interventional distributions, not merely observed groups. It requires a randomized intervention or justified identification assumptions.",formula:"ACE = E[Y|do(X=x₁)] − E[Y|do(X=x₀)]",formulaNote:"An observational difference E[Y|X=x₁]−E[Y|X=x₀] equals ACE only under sufficient assumptions.",project:"The frontend labels drift-based mechanism claims as open and proposes acquisition-matched interventions.",sources:["causalBook","projectContract","projectCifar"],related:["observational-result","confounding","mediation"]});
  add({id:"observational-result",name:"Observational result",aliases:["observational","observation","observed result","observational result","descriptive"],category:"Experimental design",summary:"A measured association or pattern reported without claiming that one variable caused another.",definition:"Observational evidence describes what co-occurred under the realized protocol. It can falsify some simple expectations and motivate interventions, but it does not by itself identify counterfactual effects.",formula:"Observed association: Δ_obs=E[Y|X=a]−E[Y|X=b]",formulaNote:"Δ_obs is descriptive unless the design and assumptions justify replacing conditioning with intervention.",project:"Representation drift, label alignment and their correlations are presented as observations with an explicit causal ceiling.",sources:["causalBook","projectCifar"],related:["causal-claim","confounding","representation-drift"]});
  add({id:"model-width",name:"Model width",aliases:["model width","width","hidden width","wide"],category:"Experimental design",summary:"The number of units or channels allocated to one or more hidden layers.",definition:"Increasing width increases the dimensionality of hidden representations and usually increases parameter count. A width intervention must keep other protocol elements fixed to support a capacity interpretation.",formula:"Dense hidden parameters scale approximately as O(d_in·w + w² + w·d_out)",formulaNote:"The precise scaling depends on how many layers are widened.",project:"The width experiment compares 256×2 with 512×2 under a frozen learning recipe.",sources:["deepLearningBook","projectContract"],related:["parameter-count","model-depth","fully-connected-layer"]});
  add({id:"model-depth",name:"Model depth",aliases:["model depth","depth","deep model","four-layer","two-layer"],category:"Experimental design",summary:"The number of successive learned transformations between input and output.",definition:"Greater depth composes more nonlinear transformations and lengthens the path through which credit information must propagate. Depth effects cannot be isolated if optimization and inference budgets change simultaneously.",formula:"f_θ = f_L∘f_{L−1}∘…∘f_1",formulaNote:"L denotes the number of composed learned layers under the study's counting convention.",project:"The depth experiment compares two versus four hidden layers with PC relaxation fixed at T=5.",sources:["deepLearningBook","projectContract"],related:["model-width","relaxation","update-alignment"]});

  window.RESEARCH_WIKI = {sources:SOURCES, terms:TERMS};
})();
